stage_a_raw:
{
  "decisions": [
    {
      "decision": "flow_variable_domain",
      "evidence": "none (the text gives demands and capacities in units but never states whether shipments must be whole units)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "\"ensure that the demand at each retail store is met\"",
      "options": [
        "sum_i x[i,j] >= demand[j]",
        "sum_i x[i,j] == demand[j]"
      ],
      "plausibility": [
        0.6,
        0.4
      ],
      "majority_option": "sum_i x[i,j] >= demand[j]"
    },
    {
      "decision": "capacity_link_form",
      "evidence": "\"Each distribution center has ... a specific supply capacity, which limits the amount of product it can dispatch\"",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] <= capacity[i] and x[i,j] <= capacity[i]*y[i] per arc"
      ],
      "plausibility": [
        0.85,
        0.15
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "objective_units_scale",
      "evidence": "\"Opening Costs ... (in dollars)\" and \"Transportation Cost Per Unit ... (in dollars)\"",
      "options": [
        "total cost in dollars (opening + per-unit transport)",
        "total cost in thousands of dollars"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "total cost in dollars (opening + per-unit transport)"
    },
    {
      "decision": "open_variable_domain",
      "evidence": "\"identifying the most cost-effective way to distribute\" / \"opening costs of the distribution centers\"",
      "options": [
        "Binary y[i]",
        "Continuous y[i] in [0,1]"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "Binary y[i]"
    },
    {
      "decision": "transport_cost_index_orientation",
      "evidence": "\"Transportation Cost Per Unit from Each Distribution Center to Retail Stores\"",
      "options": [
        "trans_cost[(center, store)] with rows=centers, columns=stores",
        "trans_cost[(store, center)] with rows=stores, columns=centers"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "trans_cost[(center, store)] with rows=centers, columns=stores"
    }
  ]
}
